-- ---------------------------------------------------------------------------
-- Durable block records
-- ---------------------------------------------------------------------------

CREATE TABLE hocalist.conversation_blocks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  conversation_id uuid NOT NULL REFERENCES hocalist.conversations(id) ON DELETE CASCADE,
  blocker_user_id uuid NOT NULL REFERENCES hocalist.profiles(id),
  blocked_user_id uuid NOT NULL REFERENCES hocalist.profiles(id),
  -- Optional review context. The reason is never returned to the blocked
  -- member and never becomes an account penalty by itself.
  reason_code text CHECK (
    reason_code IS NULL OR reason_code IN ('safety','harassment','spam','deal_dispute','other')
  ),
  created_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz,
  CONSTRAINT conversation_blocks_distinct CHECK (blocker_user_id <> blocked_user_id),
  CONSTRAINT conversation_blocks_revoked_after_created CHECK (
    revoked_at IS NULL OR revoked_at >= created_at
  )
);
CREATE UNIQUE INDEX conversation_blocks_active_pair
  ON hocalist.conversation_blocks(conversation_id, blocker_user_id, blocked_user_id)
  WHERE revoked_at IS NULL;
CREATE INDEX conversation_blocks_blocked_lookup
  ON hocalist.conversation_blocks(conversation_id, blocked_user_id)
  WHERE revoked_at IS NULL;
CREATE INDEX conversation_blocks_blocker_lookup
  ON hocalist.conversation_blocks(conversation_id, blocker_user_id)
  WHERE revoked_at IS NULL;

ALTER TABLE hocalist.conversation_blocks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON hocalist.conversation_blocks FROM PUBLIC, anon, authenticated, service_role;

-- Defense in depth: no client table grant exists, so this policy is inert
-- today and exists so a future reviewed grant cannot expose another member's
-- block records. All functional access goes through the RPCs below.
CREATE POLICY chat_member_block_read ON hocalist.conversation_blocks
  FOR SELECT TO authenticated
  USING (hocalist.chat_is_member(conversation_id, (SELECT auth.uid())));

-- New messages are refused in both directions while any active block exists
-- for the sender in that conversation. This is a table trigger so every write
-- path (text send, attachment send, any later internal path) is covered.
CREATE FUNCTION hocalist.chat_block_enforce_insert()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM hocalist.conversation_blocks b
    WHERE b.conversation_id = NEW.conversation_id
      AND b.revoked_at IS NULL
      AND (b.blocker_user_id = NEW.sender_user_id OR b.blocked_user_id = NEW.sender_user_id)
  ) THEN
    RAISE EXCEPTION 'conversation_blocked' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER chat_block_enforce_message
  BEFORE INSERT ON hocalist.conversation_messages
  FOR EACH ROW EXECUTE FUNCTION hocalist.chat_block_enforce_insert();

-- ---------------------------------------------------------------------------
-- Read/participation enforcement (replaces the reviewed 010 definitions)
-- ---------------------------------------------------------------------------

-- Same contract as 010 plus one addition: a member who is the blocked party of
-- an active block is denied every participant operation that routes through
-- this helper (messages, conversation read, send, mark-read, mute and calls).
-- The blocker is not denied by this helper, so they retain their own history
-- and can reverse the block.
CREATE OR REPLACE FUNCTION hocalist.chat_assert_participant(p_conversation uuid, p_user uuid)
RETURNS hocalist.conversation_members
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  m hocalist.conversation_members%ROWTYPE;
BEGIN
  IF p_user IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO m FROM hocalist.conversation_members
    WHERE conversation_id = p_conversation AND user_id = p_user;
  IF NOT FOUND OR m.revoked_at IS NOT NULL THEN
    RAISE EXCEPTION 'conversation_access_denied' USING ERRCODE='42501';
  END IF;
  IF EXISTS (SELECT 1 FROM hocalist.memberships
             WHERE user_id = p_user AND status IN ('restricted','disabled')) THEN
    RAISE EXCEPTION 'account_restricted' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM hocalist.memberships
                 WHERE id = m.profile_id AND user_id = p_user
                   AND role = m.role AND status = 'active') THEN
    RAISE EXCEPTION 'role_not_active' USING ERRCODE='42501';
  END IF;
  IF EXISTS (SELECT 1 FROM hocalist.conversation_blocks b
             WHERE b.conversation_id = p_conversation
               AND b.revoked_at IS NULL
               AND b.blocked_user_id = p_user) THEN
    RAISE EXCEPTION 'conversation_blocked' USING ERRCODE='42501';
  END IF;
  RETURN m;
END; $$;

-- Same contract as 010 plus: a member who is the blocked party of an active
-- block does not see the conversation in their inbox. A blocker keeps the row
-- so the block state (and its reverse action) stays reachable.
CREATE OR REPLACE FUNCTION hocalist.chat_inbox(p_page_size integer DEFAULT 50, p_cursor text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_user uuid := auth.uid();
  v_size integer;
  v_cursor_seq bigint;
  v_cursor_id uuid;
  v_last_seq bigint;
  v_last_id uuid;
  v_items jsonb;
  v_next text;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF EXISTS (SELECT 1 FROM hocalist.memberships
             WHERE user_id = v_user AND status IN ('restricted','disabled')) THEN
    RAISE EXCEPTION 'account_restricted' USING ERRCODE='42501';
  END IF;
  v_size := greatest(1, least(coalesce(p_page_size, 50), 100));
  IF p_cursor IS NOT NULL THEN
    BEGIN
      v_cursor_seq := split_part(p_cursor, '.', 1)::bigint;
      v_cursor_id := split_part(p_cursor, '.', 2)::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_cursor' USING ERRCODE='22023';
    END;
  END IF;

  SELECT coalesce(jsonb_agg(row_json ORDER BY row_seq DESC, row_id DESC), '[]'::jsonb)
  INTO v_items
  FROM (
    SELECT c.id AS row_id,
           coalesce(latest.seq, 0) AS row_seq,
           jsonb_build_object(
             'conversation', hocalist.chat_conversation_json(c.id),
             'counterpart_display_name', coalesce(nullif(btrim(counterpart.display_name), ''), 'Hocalist member'),
             'counterpart_profile_id', counterpart_member.profile_id,
             'latest_message', latest.message,
             'unread_count', (
               SELECT count(*)::integer FROM hocalist.conversation_messages m
               WHERE m.conversation_id = c.id AND m.seq > self.last_read_seq
                 AND m.sender_user_id <> v_user
             )
           ) AS row_json
    FROM hocalist.conversation_members self
    JOIN hocalist.conversations c ON c.id = self.conversation_id
    LEFT JOIN LATERAL (
      SELECT m.seq, to_jsonb(m) AS message FROM hocalist.conversation_messages m
      WHERE m.conversation_id = c.id ORDER BY m.seq DESC LIMIT 1
    ) latest ON true
    LEFT JOIN LATERAL (
      SELECT om.profile_id FROM hocalist.conversation_members om
      WHERE om.conversation_id = c.id AND om.user_id <> v_user
      ORDER BY om.joined_at, om.user_id LIMIT 1
    ) counterpart_member ON true
    LEFT JOIN hocalist.role_profiles counterpart ON counterpart.membership_id = counterpart_member.profile_id
    WHERE self.user_id = v_user AND self.revoked_at IS NULL
      AND NOT EXISTS (
        SELECT 1 FROM hocalist.conversation_blocks b
        WHERE b.conversation_id = c.id AND b.revoked_at IS NULL
          AND b.blocked_user_id = v_user
      )
      AND EXISTS (
        SELECT 1 FROM hocalist.memberships m
        WHERE m.id = self.profile_id AND m.user_id = v_user
          AND m.role = self.role AND m.status = 'active'
      )
      AND (p_cursor IS NULL OR (coalesce(latest.seq, 0), c.id) < (v_cursor_seq, v_cursor_id))
    ORDER BY coalesce(latest.seq, 0) DESC, c.id DESC
    LIMIT v_size
  ) rows;

  v_next := NULL;
  IF jsonb_array_length(v_items) = v_size THEN
    v_last_seq := coalesce((v_items->-1->'latest_message'->>'seq')::bigint, 0);
    v_last_id := (v_items->-1->'conversation'->>'id')::uuid;
    IF EXISTS (
      SELECT 1 FROM hocalist.conversation_members self
      JOIN hocalist.conversations c ON c.id = self.conversation_id
      LEFT JOIN LATERAL (
        SELECT m.seq FROM hocalist.conversation_messages m
        WHERE m.conversation_id = c.id ORDER BY m.seq DESC LIMIT 1
      ) latest ON true
      WHERE self.user_id = v_user AND self.revoked_at IS NULL
        AND NOT EXISTS (
          SELECT 1 FROM hocalist.conversation_blocks b
          WHERE b.conversation_id = c.id AND b.revoked_at IS NULL
            AND b.blocked_user_id = v_user
        )
        AND EXISTS (
          SELECT 1 FROM hocalist.memberships m
          WHERE m.id = self.profile_id AND m.user_id = v_user
            AND m.role = self.role AND m.status = 'active'
        )
        AND (coalesce(latest.seq, 0), c.id) < (v_last_seq, v_last_id)
    ) THEN
      v_next := v_last_seq::text || '.' || v_last_id::text;
    END IF;
  END IF;

  RETURN jsonb_build_object('items', v_items, 'next_cursor', v_next);
END; $$;

-- ---------------------------------------------------------------------------
-- Client RPCs
-- ---------------------------------------------------------------------------

-- Creates (or returns) one active block from the caller to every other
-- unrevoked member of the conversation. Idempotent. It deliberately changes
-- nothing else: no offer, meeting, credit, reward, message or membership row
-- is touched.
CREATE FUNCTION hocalist.chat_block(p_conversation uuid, p_reason text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_user uuid := auth.uid();
  v_member hocalist.conversation_members%ROWTYPE;
  v_peer uuid;
BEGIN
  SELECT * INTO v_member FROM hocalist.chat_assert_participant(p_conversation, v_user);
  IF p_reason IS NOT NULL AND p_reason NOT IN ('safety','harassment','spam','deal_dispute','other') THEN
    RAISE EXCEPTION 'invalid_field: p_reason' USING ERRCODE='22023';
  END IF;
  FOR v_peer IN
    SELECT user_id FROM hocalist.conversation_members
    WHERE conversation_id = p_conversation AND revoked_at IS NULL AND user_id <> v_user
  LOOP
    INSERT INTO hocalist.conversation_blocks(
      conversation_id, blocker_user_id, blocked_user_id, reason_code)
    VALUES (p_conversation, v_user, v_peer, p_reason)
    ON CONFLICT (conversation_id, blocker_user_id, blocked_user_id)
      WHERE revoked_at IS NULL DO NOTHING;
  END LOOP;
  -- A live call in this conversation ends deterministically when the block is
  -- recorded. Only the call state changes; the signaling rows are pruned by
  -- the next call command/status sweep. Calls may not be deployed yet.
  IF to_regclass('hocalist.calls') IS NOT NULL THEN
    EXECUTE 'UPDATE hocalist.calls SET state = ''ended''
             WHERE conversation_id = $1 AND state IN (''ringing'',''accepted'')'
      USING p_conversation;
  END IF;
  RETURN hocalist.chat_block_state(p_conversation);
END; $$;

-- Revokes the caller's own active blocks in this conversation. Idempotent.
CREATE FUNCTION hocalist.chat_unblock(p_conversation uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_user uuid := auth.uid();
  v_member hocalist.conversation_members%ROWTYPE;
BEGIN
  SELECT * INTO v_member FROM hocalist.chat_assert_participant(p_conversation, v_user);
  UPDATE hocalist.conversation_blocks
    SET revoked_at = now()
    WHERE conversation_id = p_conversation AND blocker_user_id = v_user
      AND revoked_at IS NULL;
  RETURN hocalist.chat_block_state(p_conversation);
END; $$;

-- Block state for the caller only. Deliberately does not use the participant
-- helper so the blocked member can still read their own "messages are not
-- available" state and refresh the UI. `is_blocked_by_me` is only ever true
-- for the blocker; `can_message` is false when any active block involves the
-- caller or the conversation is closed.
CREATE FUNCTION hocalist.chat_block_state(p_conversation uuid)
RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_user uuid := auth.uid();
  v_member hocalist.conversation_members%ROWTYPE;
  v_status text;
  v_mine boolean;
  v_theirs boolean;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_member FROM hocalist.conversation_members
    WHERE conversation_id = p_conversation AND user_id = v_user;
  IF NOT FOUND OR v_member.revoked_at IS NOT NULL THEN
    RAISE EXCEPTION 'conversation_access_denied' USING ERRCODE='42501';
  END IF;
  IF EXISTS (SELECT 1 FROM hocalist.memberships
             WHERE user_id = v_user AND status IN ('restricted','disabled')) THEN
    RAISE EXCEPTION 'account_restricted' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM hocalist.memberships
                 WHERE id = v_member.profile_id AND user_id = v_user
                   AND role = v_member.role AND status = 'active') THEN
    RAISE EXCEPTION 'role_not_active' USING ERRCODE='42501';
  END IF;
  SELECT status INTO v_status FROM hocalist.conversations WHERE id = p_conversation;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'conversation_access_denied' USING ERRCODE='42501';
  END IF;
  v_mine := EXISTS (
    SELECT 1 FROM hocalist.conversation_blocks b
    WHERE b.conversation_id = p_conversation AND b.revoked_at IS NULL
      AND b.blocker_user_id = v_user
  );
  v_theirs := EXISTS (
    SELECT 1 FROM hocalist.conversation_blocks b
    WHERE b.conversation_id = p_conversation AND b.revoked_at IS NULL
      AND b.blocked_user_id = v_user
  );
  RETURN jsonb_build_object(
    'conversation_id', p_conversation,
    'is_blocked_by_me', v_mine,
    'blocked_by_counterpart', v_theirs,
    'conversation_status', v_status,
    'can_message', v_status = 'open' AND NOT v_mine AND NOT v_theirs
  );
END; $$;

-- ---------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------

REVOKE ALL ON FUNCTION hocalist.chat_block_enforce_insert()
  FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION hocalist.chat_block(uuid,text), hocalist.chat_unblock(uuid),
  hocalist.chat_block_state(uuid)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION hocalist.chat_block(uuid,text), hocalist.chat_unblock(uuid),
  hocalist.chat_block_state(uuid)
  TO authenticated;

DO $hocalist_chat_block_postapply$
DECLARE
  v_issues text[] := ARRAY[]::text[];
  v_fn text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgrelid = 'hocalist.conversation_messages'::regclass
      AND tgname = 'chat_block_enforce_message' AND NOT tgisinternal
  ) THEN
    v_issues := array_append(v_issues, 'missing block enforcement trigger');
  END IF;
  FOREACH v_fn IN ARRAY ARRAY[
    'chat_block(uuid,text)','chat_unblock(uuid)','chat_block_state(uuid)'] LOOP
    IF NOT has_function_privilege('authenticated', 'hocalist.' || v_fn, 'EXECUTE')
       OR has_function_privilege('anon', 'hocalist.' || v_fn, 'EXECUTE') THEN
      v_issues := array_append(v_issues, 'block function grants are wrong: ' || v_fn);
    END IF;
  END LOOP;
  IF has_function_privilege('authenticated','hocalist.chat_block_enforce_insert()','EXECUTE')
     OR has_function_privilege('anon','hocalist.chat_block_enforce_insert()','EXECUTE') THEN
    v_issues := array_append(v_issues, 'block trigger function is executable');
  END IF;
  IF has_table_privilege('authenticated','hocalist.conversation_blocks','SELECT')
     OR has_table_privilege('anon','hocalist.conversation_blocks','SELECT')
     OR NOT (SELECT relrowsecurity FROM pg_class
             WHERE oid = 'hocalist.conversation_blocks'::regclass) THEN
    v_issues := array_append(v_issues, 'block table exposure differs from the reviewed shape');
  END IF;
  IF position('conversation_blocked' in pg_get_functiondef(
       to_regprocedure('hocalist.chat_assert_participant(uuid,uuid)'))) = 0
     OR position('conversation_blocks' in pg_get_functiondef(
       to_regprocedure('hocalist.chat_inbox(integer,text)'))) = 0 THEN
    v_issues := array_append(v_issues, 'block enforcement was not applied to the chat reads');
  END IF;
  IF NOT has_function_privilege('authenticated','hocalist.chat_send(uuid,text,text)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.chat_messages(uuid,integer,uuid)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.account_command(text,text,jsonb)','EXECUTE') THEN
    v_issues := array_append(v_issues, 'deployed chat/account grants changed');
  END IF;
  IF coalesce(array_length(v_issues, 1), 0) > 0 THEN
    RAISE EXCEPTION 'hocalist chat block post-apply verification failed: %',
      array_to_string(v_issues, ' | ');
  END IF;
END
$hocalist_chat_block_postapply$;
-- ---------------------------------------------------------------------------
-- 151_chat_search.sql
-- ---------------------------------------------------------------------------
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';
DO $chat_search_guard$
BEGIN
  IF to_regclass('hocalist.conversations') IS NULL
     OR to_regclass('hocalist.conversation_members') IS NULL
     OR to_regclass('hocalist.conversation_messages') IS NULL
     OR to_regprocedure('hocalist.chat_conversation_json(uuid)') IS NULL THEN
    RAISE EXCEPTION 'Chat foundation 010 is missing';
  END IF;
  IF to_regclass('hocalist.conversation_blocks') IS NULL THEN
    RAISE EXCEPTION 'Chat block contract 150 is missing';
  END IF;
  IF to_regprocedure('hocalist.chat_search(text,integer,text,uuid)') IS NOT NULL
     OR to_regprocedure('hocalist.chat_search_inbox(text,integer,text)') IS NOT NULL THEN
    RAISE EXCEPTION 'Chat search objects already exist; review before applying';
  END IF;
END
$chat_search_guard$;

-- One paged message search for the caller. Optional p_conversation narrows the
-- search to a conversation the caller may read; without it, every conversation
-- the caller currently belongs to is searched.
CREATE FUNCTION hocalist.chat_search(
  p_query text,
  p_page_size integer DEFAULT 25,
  p_cursor text DEFAULT NULL,
  p_conversation uuid DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_user uuid := auth.uid();
  v_query text;
  v_size integer;
  v_cursor_seq bigint;
  v_cursor_id uuid;
  v_last_seq bigint;
  v_last_id uuid;
  v_items jsonb;
  v_next text;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501';
  END IF;
  IF EXISTS (SELECT 1 FROM hocalist.memberships
             WHERE user_id = v_user AND status IN ('restricted','disabled')) THEN
    RAISE EXCEPTION 'account_restricted' USING ERRCODE='42501';
  END IF;
  IF p_query IS NULL OR length(btrim(p_query)) NOT BETWEEN 2 AND 64 THEN
    RAISE EXCEPTION 'invalid_field: p_query' USING ERRCODE='22023';
  END IF;
  v_query := lower(btrim(p_query));
  v_size := greatest(1, least(coalesce(p_page_size, 25), 50));
  IF p_cursor IS NOT NULL THEN
    BEGIN
      v_cursor_seq := split_part(p_cursor, '.', 1)::bigint;
      v_cursor_id := split_part(p_cursor, '.', 2)::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_cursor' USING ERRCODE='22023';
    END;
  END IF;
  -- Scoped search reuses the participant fence so a blocked, revoked or
  -- inactive member gets the same typed denial here as on a direct read.
  IF p_conversation IS NOT NULL THEN
    PERFORM hocalist.chat_assert_participant(p_conversation, v_user);
  END IF;

  SELECT coalesce(jsonb_agg(row_json ORDER BY row_seq DESC, row_id DESC), '[]'::jsonb)
  INTO v_items
  FROM (
    SELECT m.seq AS row_seq,
           m.id AS row_id,
           jsonb_build_object(
             'message', to_jsonb(m),
             'conversation_id', m.conversation_id,
             'conversation_origin', c.origin,
             'conversation_status', c.status,
             'counterpart_display_name', coalesce(nullif(btrim(counterpart.display_name), ''), 'Hocalist member'),
             'counterpart_profile_id', counterpart_member.profile_id
           ) AS row_json
    FROM hocalist.conversation_members self
    JOIN hocalist.conversations c ON c.id = self.conversation_id
    JOIN hocalist.conversation_messages m ON m.conversation_id = c.id
    LEFT JOIN LATERAL (
      SELECT om.profile_id FROM hocalist.conversation_members om
      WHERE om.conversation_id = c.id AND om.user_id <> v_user
      ORDER BY om.joined_at, om.user_id LIMIT 1
    ) counterpart_member ON true
    LEFT JOIN hocalist.role_profiles counterpart
      ON counterpart.membership_id = counterpart_member.profile_id
    WHERE self.user_id = v_user AND self.revoked_at IS NULL
      AND EXISTS (
        SELECT 1 FROM hocalist.memberships ms
        WHERE ms.id = self.profile_id AND ms.user_id = v_user
          AND ms.role = self.role AND ms.status = 'active'
      )
      AND NOT EXISTS (
        SELECT 1 FROM hocalist.conversation_blocks b
        WHERE b.conversation_id = c.id AND b.revoked_at IS NULL
          AND b.blocked_user_id = v_user
      )
      AND (p_conversation IS NULL OR c.id = p_conversation)
      AND position(v_query in lower(m.text)) > 0
      AND (p_cursor IS NULL OR (m.seq, m.id) < (v_cursor_seq, v_cursor_id))
    ORDER BY m.seq DESC, m.id DESC
    LIMIT v_size
  ) rows;

  v_next := NULL;
  IF jsonb_array_length(v_items) = v_size THEN
    v_last_seq := (v_items->-1->'message'->>'seq')::bigint;
    v_last_id := (v_items->-1->'message'->>'id')::uuid;
    IF EXISTS (
      SELECT 1 FROM hocalist.conversation_members self
      JOIN hocalist.conversations c ON c.id = self.conversation_id
      JOIN hocalist.conversation_messages m ON m.conversation_id = c.id
      WHERE self.user_id = v_user AND self.revoked_at IS NULL
        AND EXISTS (
          SELECT 1 FROM hocalist.memberships ms
          WHERE ms.id = self.profile_id AND ms.user_id = v_user
            AND ms.role = self.role AND ms.status = 'active'
        )
        AND NOT EXISTS (
          SELECT 1 FROM hocalist.conversation_blocks b
          WHERE b.conversation_id = c.id AND b.revoked_at IS NULL
            AND b.blocked_user_id = v_user
        )
        AND (p_conversation IS NULL OR c.id = p_conversation)
        AND position(v_query in lower(m.text)) > 0
        AND (m.seq, m.id) < (v_last_seq, v_last_id)
    ) THEN
      v_next := v_last_seq::text || '.' || v_last_id::text;
    END IF;
  END IF;

  RETURN jsonb_build_object('items', v_items, 'next_cursor', v_next);
END; $$;

-- One paged conversation search over the caller's own inbox rows, matched on
-- the counterpart display name. Cursor format matches chat_inbox.
CREATE FUNCTION hocalist.chat_search_inbox(
  p_query text,
  p_page_size integer DEFAULT 25,
  p_cursor text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_user uuid := auth.uid();
  v_query text;
  v_size integer;
  v_cursor_seq bigint;
  v_cursor_id uuid;
  v_last_seq bigint;
  v_last_id uuid;
  v_items jsonb;
  v_next text;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501';
  END IF;
  IF EXISTS (SELECT 1 FROM hocalist.memberships
             WHERE user_id = v_user AND status IN ('restricted','disabled')) THEN
    RAISE EXCEPTION 'account_restricted' USING ERRCODE='42501';
  END IF;
  IF p_query IS NULL OR length(btrim(p_query)) NOT BETWEEN 2 AND 64 THEN
    RAISE EXCEPTION 'invalid_field: p_query' USING ERRCODE='22023';
  END IF;
  v_query := lower(btrim(p_query));
  v_size := greatest(1, least(coalesce(p_page_size, 25), 50));
  IF p_cursor IS NOT NULL THEN
    BEGIN
      v_cursor_seq := split_part(p_cursor, '.', 1)::bigint;
      v_cursor_id := split_part(p_cursor, '.', 2)::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_cursor' USING ERRCODE='22023';
    END;
  END IF;

  SELECT coalesce(jsonb_agg(row_json ORDER BY row_seq DESC, row_id DESC), '[]'::jsonb)
  INTO v_items
  FROM (
    SELECT c.id AS row_id,
           coalesce(latest.seq, 0) AS row_seq,
           jsonb_build_object(
             'conversation', hocalist.chat_conversation_json(c.id),
             'counterpart_display_name', coalesce(nullif(btrim(counterpart.display_name), ''), 'Hocalist member'),
             'counterpart_profile_id', counterpart_member.profile_id,
             'latest_message', latest.message,
             'unread_count', (
               SELECT count(*)::integer FROM hocalist.conversation_messages m
               WHERE m.conversation_id = c.id AND m.seq > self.last_read_seq
                 AND m.sender_user_id <> v_user
             )
           ) AS row_json
    FROM hocalist.conversation_members self
    JOIN hocalist.conversations c ON c.id = self.conversation_id
    LEFT JOIN LATERAL (
      SELECT m.seq, to_jsonb(m) AS message FROM hocalist.conversation_messages m
      WHERE m.conversation_id = c.id ORDER BY m.seq DESC LIMIT 1
    ) latest ON true
    LEFT JOIN LATERAL (
      SELECT om.profile_id FROM hocalist.conversation_members om
      WHERE om.conversation_id = c.id AND om.user_id <> v_user
      ORDER BY om.joined_at, om.user_id LIMIT 1
    ) counterpart_member ON true
    LEFT JOIN hocalist.role_profiles counterpart
      ON counterpart.membership_id = counterpart_member.profile_id
    WHERE self.user_id = v_user AND self.revoked_at IS NULL
      AND EXISTS (
        SELECT 1 FROM hocalist.memberships ms
        WHERE ms.id = self.profile_id AND ms.user_id = v_user
          AND ms.role = self.role AND ms.status = 'active'
      )
      AND NOT EXISTS (
        SELECT 1 FROM hocalist.conversation_blocks b
        WHERE b.conversation_id = c.id AND b.revoked_at IS NULL
          AND b.blocked_user_id = v_user
      )
      AND position(v_query in lower(coalesce(counterpart.display_name, ''))) > 0
      AND (p_cursor IS NULL OR (coalesce(latest.seq, 0), c.id) < (v_cursor_seq, v_cursor_id))
    ORDER BY coalesce(latest.seq, 0) DESC, c.id DESC
    LIMIT v_size
  ) rows;

  v_next := NULL;
  IF jsonb_array_length(v_items) = v_size THEN
    v_last_seq := coalesce((v_items->-1->'latest_message'->>'seq')::bigint, 0);
    v_last_id := (v_items->-1->'conversation'->>'id')::uuid;
    IF EXISTS (
      SELECT 1 FROM hocalist.conversation_members self
      JOIN hocalist.conversations c ON c.id = self.conversation_id
      LEFT JOIN LATERAL (
        SELECT m.seq FROM hocalist.conversation_messages m
        WHERE m.conversation_id = c.id ORDER BY m.seq DESC LIMIT 1
      ) latest ON true
      LEFT JOIN LATERAL (
        SELECT om.profile_id FROM hocalist.conversation_members om
        WHERE om.conversation_id = c.id AND om.user_id <> v_user
        ORDER BY om.joined_at, om.user_id LIMIT 1
      ) counterpart_member ON true
      LEFT JOIN hocalist.role_profiles counterpart
        ON counterpart.membership_id = counterpart_member.profile_id
      WHERE self.user_id = v_user AND self.revoked_at IS NULL
        AND EXISTS (
          SELECT 1 FROM hocalist.memberships ms
          WHERE ms.id = self.profile_id AND ms.user_id = v_user
            AND ms.role = self.role AND ms.status = 'active'
        )
        AND NOT EXISTS (
          SELECT 1 FROM hocalist.conversation_blocks b
          WHERE b.conversation_id = c.id AND b.revoked_at IS NULL
            AND b.blocked_user_id = v_user
        )
        AND position(v_query in lower(coalesce(counterpart.display_name, ''))) > 0
        AND (coalesce(latest.seq, 0), c.id) < (v_last_seq, v_last_id)
    ) THEN
      v_next := v_last_seq::text || '.' || v_last_id::text;
    END IF;
  END IF;

  RETURN jsonb_build_object('items', v_items, 'next_cursor', v_next);
END; $$;

-- ---------------------------------------------------------------------------
-- Grants and post-apply verification
-- ---------------------------------------------------------------------------

REVOKE ALL ON FUNCTION hocalist.chat_search(text,integer,text,uuid),
  hocalist.chat_search_inbox(text,integer,text)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION hocalist.chat_search(text,integer,text,uuid),
  hocalist.chat_search_inbox(text,integer,text)
  TO authenticated;

DO $hocalist_chat_search_postapply$
DECLARE
  v_issues text[] := ARRAY[]::text[];
  v_fn text;
BEGIN
  FOREACH v_fn IN ARRAY ARRAY[
    'chat_search(text,integer,text,uuid)','chat_search_inbox(text,integer,text)'] LOOP
    IF NOT has_function_privilege('authenticated', 'hocalist.' || v_fn, 'EXECUTE')
       OR has_function_privilege('anon', 'hocalist.' || v_fn, 'EXECUTE')
       OR has_function_privilege('service_role', 'hocalist.' || v_fn, 'EXECUTE') THEN
      v_issues := array_append(v_issues, 'search function grants are wrong: ' || v_fn);
    END IF;
  END LOOP;
  IF NOT has_function_privilege('authenticated','hocalist.chat_messages(uuid,integer,uuid)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.chat_inbox(integer,text)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.account_command(text,text,jsonb)','EXECUTE') THEN
    v_issues := array_append(v_issues, 'deployed chat/account grants changed');
  END IF;
  IF coalesce(array_length(v_issues, 1), 0) > 0 THEN
    RAISE EXCEPTION 'hocalist chat search post-apply verification failed: %',
      array_to_string(v_issues, ' | ');
  END IF;
END
$hocalist_chat_search_postapply$;
-- ---------------------------------------------------------------------------
-- 152_call_status.sql
-- ---------------------------------------------------------------------------
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';
DO $call_status_guard$
BEGIN
  IF to_regclass('hocalist.calls') IS NULL
     OR to_regclass('hocalist.call_signals') IS NULL
     OR to_regclass('hocalist.call_settings') IS NULL
     OR to_regprocedure('hocalist.call_command(text,jsonb)') IS NULL
     OR to_regprocedure('hocalist.chat_assert_participant(uuid,uuid)') IS NULL THEN
    RAISE EXCEPTION 'Call signaling 110 is missing';
  END IF;
  IF md5(replace(pg_get_functiondef(to_regprocedure('hocalist.call_command(text,jsonb)')),chr(13),''))
       <> '49221a424fc1c80032f56da8a71de9bd' THEN
    RAISE EXCEPTION 'Prerequisite drift: hocalist.call_command(text,jsonb)';
  END IF;
  IF to_regprocedure('hocalist.call_status(uuid,bigint)') IS NOT NULL THEN
    RAISE EXCEPTION 'Call status object already exists; review before applying';
  END IF;
END
$call_status_guard$;

CREATE FUNCTION hocalist.call_status(p_call_id uuid, p_cursor bigint DEFAULT 0)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_user uuid := auth.uid();
  c hocalist.calls%ROWTYPE;
  s hocalist.call_settings%ROWTYPE;
  items jsonb;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501';
  END IF;
  IF p_call_id IS NULL THEN
    RAISE EXCEPTION 'invalid_field: p_call_id' USING ERRCODE='22023';
  END IF;
  IF p_cursor IS NOT NULL AND p_cursor < 0 THEN
    RAISE EXCEPTION 'invalid_cursor' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM hocalist.memberships WHERE user_id = v_user AND status = 'active')
     OR EXISTS (SELECT 1 FROM hocalist.memberships
                WHERE user_id = v_user AND status IN ('restricted','disabled')) THEN
    RAISE EXCEPTION 'call_access_denied' USING ERRCODE='42501';
  END IF;
  -- Serialize with the call control plane so the timeout sweep and the call
  -- command cannot observe or write different states concurrently.
  PERFORM pg_advisory_xact_lock(110,1);
  UPDATE hocalist.calls SET state = CASE WHEN state = 'ringing' THEN 'missed' ELSE 'ended' END
    WHERE state IN ('ringing','accepted') AND expires_at <= now();
  DELETE FROM hocalist.call_signals s2 USING hocalist.calls d
    WHERE s2.call_id = d.id AND d.state NOT IN ('ringing','accepted');

  SELECT * INTO c FROM hocalist.calls WHERE id = p_call_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'call_not_found' USING ERRCODE='P0002';
  END IF;
  IF v_user NOT IN (c.caller_id, c.callee_id) THEN
    RAISE EXCEPTION 'call_access_denied' USING ERRCODE='42501';
  END IF;
  -- Read-only status keeps the participant check (an unrevoked conversation
  -- member plus an active role membership) so either participant can observe a
  -- terminal state and close media. Restricted/disabled accounts are denied by
  -- the account check above, exactly like the participant fence; a blocked
  -- member can still read status but cannot exchange signals or invites. Writes
  -- still go through the 150-fenced call command.
  PERFORM 1 FROM hocalist.conversation_members cm
    WHERE cm.conversation_id = c.conversation_id AND cm.user_id = v_user
      AND cm.revoked_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'call_access_denied' USING ERRCODE='42501';
  END IF;
  SELECT * INTO s FROM hocalist.call_settings WHERE singleton;

  SELECT coalesce(jsonb_agg(jsonb_build_object('seq', sig.seq, 'kind', sig.kind, 'payload', sig.payload)
           ORDER BY sig.seq), '[]'::jsonb)
  INTO items
  FROM hocalist.call_signals sig
  WHERE sig.call_id = c.id AND sig.sender_id <> v_user
    AND sig.seq > coalesce(p_cursor, 0);

  RETURN jsonb_build_object(
    'call', jsonb_build_object(
      'id', c.id,
      'conversation_id', c.conversation_id,
      'caller_id', c.caller_id,
      'callee_id', c.callee_id,
      'state', c.state,
      'created_at', c.created_at,
      'expires_at', c.expires_at,
      'terminal', c.state NOT IN ('ringing','accepted')
    ),
    'signals', items,
    'server_now', now(),
    'enabled', coalesce(s.enabled, false),
    'settings_revision', coalesce(s.revision, 0)
  );
END; $$;

REVOKE ALL ON FUNCTION hocalist.call_status(uuid,bigint)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION hocalist.call_status(uuid,bigint) TO authenticated;

DO $hocalist_call_status_postapply$
DECLARE
  v_issues text[] := ARRAY[]::text[];
BEGIN
  IF NOT has_function_privilege('authenticated','hocalist.call_status(uuid,bigint)','EXECUTE')
     OR has_function_privilege('anon','hocalist.call_status(uuid,bigint)','EXECUTE')
     OR has_function_privilege('service_role','hocalist.call_status(uuid,bigint)','EXECUTE') THEN
    v_issues := array_append(v_issues, 'call status grants are wrong');
  END IF;
  IF NOT has_function_privilege('authenticated','hocalist.call_command(text,jsonb)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.call_admin_settings(boolean,bigint)','EXECUTE')
     OR has_function_privilege('anon','hocalist.call_command(text,jsonb)','EXECUTE') THEN
    v_issues := array_append(v_issues, 'deployed call grants changed');
  END IF;
  IF position('terminal' in pg_get_functiondef(to_regprocedure('hocalist.call_status(uuid,bigint)'))) = 0 THEN
    v_issues := array_append(v_issues, 'call status terminal flag missing');
  END IF;
  IF coalesce(array_length(v_issues, 1), 0) > 0 THEN
    RAISE EXCEPTION 'hocalist call status post-apply verification failed: %',
      array_to_string(v_issues, ' | ');
  END IF;
END
$hocalist_call_status_postapply$;
-- ---------------------------------------------------------------------------
-- 153_communication_producers.sql
-- ---------------------------------------------------------------------------
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';
DO $communication_producer_guard$
BEGIN
  IF to_regprocedure('hocalist.notification_emit(uuid,uuid,text,uuid,text,text,text,jsonb)') IS NULL
     OR to_regprocedure('hocalist.notification_recipient_allowed(uuid)') IS NULL THEN
    RAISE EXCEPTION 'Notification inbox/producer foundation 030/031 is missing';
  END IF;
  IF to_regclass('hocalist.calls') IS NULL
     OR to_regclass('hocalist.meetings') IS NULL
     OR to_regclass('hocalist.meeting_schedule_revisions') IS NULL THEN
    RAISE EXCEPTION 'Call 110 / meeting 040 foundation is missing';
  END IF;
  IF to_regprocedure('hocalist.notification_on_call_ringing()') IS NOT NULL
     OR to_regprocedure('hocalist.notification_on_call_status()') IS NOT NULL
     OR to_regprocedure('hocalist.notification_enqueue_meeting_reminders(integer,integer)') IS NOT NULL THEN
    RAISE EXCEPTION 'Communication producers already exist; review before applying';
  END IF;
END
$communication_producer_guard$;

-- ---------------------------------------------------------------------------
-- Calls
-- ---------------------------------------------------------------------------

-- One ringing invitation notification for the callee. Deduplicated per call;
-- a retried invite returns the same call and therefore the same notification.
CREATE FUNCTION hocalist.notification_on_call_ringing() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF hocalist.notification_recipient_allowed(NEW.callee_id) THEN
    PERFORM hocalist.notification_emit(
      NEW.callee_id,
      md5('call:ringing:' || NEW.id::text)::uuid,
      'meeting_update',
      NEW.id,
      'Incoming Hocalist call',
      'You have a call invitation. Open Hocalist to answer or decline.',
      'hocalist://chat/' || NEW.conversation_id::text,
      jsonb_build_object('call_id', NEW.id, 'conversation_id', NEW.conversation_id, 'state', 'ringing'));
  END IF;
  RETURN NEW;
END; $$;

CREATE TRIGGER notification_call_ringing
  AFTER INSERT ON hocalist.calls
  FOR EACH ROW EXECUTE FUNCTION hocalist.notification_on_call_ringing();

-- Ringing that never connected notifies the callee as missed when the caller
-- cancels or the invitation times out. A callee decline notifies the caller.
-- Connected calls that end do not notify either participant.
CREATE FUNCTION hocalist.notification_on_call_status() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF OLD.state = NEW.state THEN
    RETURN NEW;
  END IF;
  IF OLD.state = 'ringing' AND NEW.state IN ('missed','cancelled') THEN
    IF hocalist.notification_recipient_allowed(NEW.callee_id) THEN
      PERFORM hocalist.notification_emit(
        NEW.callee_id,
        md5('call:missed:' || NEW.id::text)::uuid,
        'meeting_update',
        NEW.id,
        'Missed call',
        'You missed a Hocalist call. Open the chat to call back.',
        'hocalist://chat/' || NEW.conversation_id::text,
        jsonb_build_object('call_id', NEW.id, 'conversation_id', NEW.conversation_id, 'state', NEW.state));
    END IF;
  ELSIF OLD.state = 'ringing' AND NEW.state = 'declined' THEN
    IF hocalist.notification_recipient_allowed(NEW.caller_id) THEN
      PERFORM hocalist.notification_emit(
        NEW.caller_id,
        md5('call:declined:' || NEW.id::text)::uuid,
        'meeting_update',
        NEW.id,
        'Call declined',
        'The call was declined. Open the chat to send a message instead.',
        'hocalist://chat/' || NEW.conversation_id::text,
        jsonb_build_object('call_id', NEW.id, 'conversation_id', NEW.conversation_id, 'state', NEW.state));
    END IF;
  END IF;
  RETURN NEW;
END; $$;

CREATE TRIGGER notification_call_status
  AFTER UPDATE OF state ON hocalist.calls
  FOR EACH ROW EXECUTE FUNCTION hocalist.notification_on_call_status();

-- ---------------------------------------------------------------------------
-- Accepted-meeting reminders (scheduler entry point, not scheduled here)
-- ---------------------------------------------------------------------------

CREATE FUNCTION hocalist.notification_enqueue_meeting_reminders(
  p_window_minutes integer DEFAULT 60,
  p_limit integer DEFAULT 200
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_count integer := 0;
  v_recipient uuid;
  v_key uuid;
  r record;
BEGIN
  IF p_window_minutes IS NULL OR p_window_minutes NOT BETWEEN 5 AND 1440 THEN
    RAISE EXCEPTION 'invalid_field: p_window_minutes' USING ERRCODE='22023';
  END IF;
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 1000 THEN
    RAISE EXCEPTION 'invalid_field: p_limit' USING ERRCODE='22023';
  END IF;
  FOR r IN
    SELECT m.id AS meeting_id,
           m.revision AS meeting_revision,
           m.buyer_user_id,
           m.seller_user_id,
           rev.schedule_instant
    FROM hocalist.meetings m
    JOIN hocalist.meeting_schedule_revisions rev ON rev.id = m.accepted_revision_id
    WHERE m.status = 'accepted'
      AND rev.status = 'accepted'
      AND rev.schedule_instant > now()
      AND rev.schedule_instant <= now() + make_interval(mins => p_window_minutes)
    ORDER BY rev.schedule_instant
    LIMIT p_limit
  LOOP
    FOREACH v_recipient IN ARRAY ARRAY[r.buyer_user_id, r.seller_user_id] LOOP
      IF hocalist.notification_recipient_allowed(v_recipient) THEN
        v_key := md5(
          'meeting:reminder:' || r.meeting_id::text || ':' ||
          r.meeting_revision::text || ':' ||
          extract(epoch from r.schedule_instant)::bigint::text
        )::uuid;
        -- Count only a genuinely new row; `notification_emit` returns the
        -- existing id for a replay so it cannot report a duplicate as queued.
        IF NOT EXISTS (
             SELECT 1 FROM hocalist.notifications n
             WHERE n.user_id = v_recipient AND n.event_key = v_key
           )
           AND hocalist.notification_emit(
             v_recipient,
             v_key,
             'meeting_update',
             r.meeting_id,
             'Meeting reminder',
             'Your accepted meeting is coming up. Open Hocalist for the details.',
             'hocalist://meetings/' || r.meeting_id::text,
             jsonb_build_object(
               'meeting_id', r.meeting_id,
               'window_minutes', p_window_minutes
             )
           ) IS NOT NULL THEN
          v_count := v_count + 1;
        END IF;
      END IF;
    END LOOP;
  END LOOP;
  RETURN jsonb_build_object('queued', v_count);
END; $$;

-- ---------------------------------------------------------------------------
-- Grants and post-apply verification
-- ---------------------------------------------------------------------------

REVOKE ALL ON FUNCTION hocalist.notification_on_call_ringing(),
  hocalist.notification_on_call_status(),
  hocalist.notification_enqueue_meeting_reminders(integer,integer)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION hocalist.notification_enqueue_meeting_reminders(integer,integer)
  TO service_role;

DO $hocalist_communication_producer_postapply$
DECLARE
  v_issues text[] := ARRAY[]::text[];
  v_entry text;
  v_table text;
  v_trigger text;
BEGIN
  FOREACH v_entry IN ARRAY ARRAY[
    'calls:notification_call_ringing','calls:notification_call_status'] LOOP
    v_table := split_part(v_entry, ':', 1);
    v_trigger := split_part(v_entry, ':', 2);
    IF NOT EXISTS (
      SELECT 1 FROM pg_trigger
      WHERE tgrelid = ('hocalist.' || v_table)::regclass
        AND tgname = v_trigger AND NOT tgisinternal
    ) THEN
      v_issues := array_append(v_issues, 'missing producer trigger: ' || v_entry);
    END IF;
  END LOOP;
  IF has_function_privilege('authenticated','hocalist.notification_on_call_ringing()','EXECUTE')
     OR has_function_privilege('authenticated','hocalist.notification_on_call_status()','EXECUTE')
     OR has_function_privilege('authenticated','hocalist.notification_enqueue_meeting_reminders(integer,integer)','EXECUTE')
     OR has_function_privilege('anon','hocalist.notification_enqueue_meeting_reminders(integer,integer)','EXECUTE')
     OR NOT has_function_privilege('service_role','hocalist.notification_enqueue_meeting_reminders(integer,integer)','EXECUTE') THEN
    v_issues := array_append(v_issues, 'producer grants are wrong');
  END IF;
  IF NOT has_function_privilege('authenticated','hocalist.notification_inbox(integer,text)','EXECUTE')
     OR has_function_privilege('authenticated','hocalist.notification_emit(uuid,uuid,text,uuid,text,text,text,jsonb)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.call_command(text,jsonb)','EXECUTE') THEN
    v_issues := array_append(v_issues, 'deployed notification/call grants changed');
  END IF;
  IF coalesce(array_length(v_issues, 1), 0) > 0 THEN
    RAISE EXCEPTION 'hocalist communication producer post-apply verification failed: %',
      array_to_string(v_issues, ' | ');
  END IF;
END
$hocalist_communication_producer_postapply$;
-- ---------------------------------------------------------------------------
-- 154_chat_realtime_signals.sql
-- ---------------------------------------------------------------------------
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';
DO $chat_signal_guard$
BEGIN
  IF to_regclass('hocalist.conversations') IS NULL
     OR to_regclass('hocalist.conversation_messages') IS NULL
     OR to_regprocedure('hocalist.chat_is_member(uuid,uuid)') IS NULL THEN
    RAISE EXCEPTION 'Chat foundation 010 is missing';
  END IF;
  IF to_regclass('hocalist.chat_change_signals') IS NOT NULL THEN
    RAISE EXCEPTION 'Chat change signals already exist; review before applying';
  END IF;
END
$chat_signal_guard$;

CREATE TABLE hocalist.chat_change_signals (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  conversation_id uuid NOT NULL REFERENCES hocalist.conversations(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX chat_change_signals_conversation_idx
  ON hocalist.chat_change_signals(conversation_id, id DESC);
ALTER TABLE hocalist.chat_change_signals ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON hocalist.chat_change_signals FROM PUBLIC, anon, authenticated, service_role;
-- Realtime checks the subscriber's SELECT privilege and this policy with the
-- subscriber's JWT; rows contain no message content. The policy helper takes
-- only the conversation id and derives the caller from auth.uid(), so a client
-- cannot use it to probe another identity's membership.
--
-- The policy mirrors the reviewed conversation-read fence: an unrevoked member
-- with a matching active role membership, no restricted/disabled membership in
-- any role, and not the blocked party of an active block. The blocker keeps
-- signal access to their own conversations. Content-free metadata still reveals
-- conversation activity, so it honors the same read boundary as messages.
GRANT SELECT ON hocalist.chat_change_signals TO authenticated;
CREATE FUNCTION hocalist.chat_signal_member(p_conversation uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (
    SELECT 1
    FROM hocalist.conversation_members m
    WHERE m.conversation_id = p_conversation
      AND m.user_id = auth.uid()
      AND m.revoked_at IS NULL
      AND EXISTS (
        SELECT 1 FROM hocalist.memberships ms
        WHERE ms.id = m.profile_id AND ms.user_id = m.user_id
          AND ms.role = m.role AND ms.status = 'active')
      AND NOT EXISTS (
        SELECT 1 FROM hocalist.memberships r
        WHERE r.user_id = auth.uid() AND r.status IN ('restricted','disabled'))
      AND NOT EXISTS (
        SELECT 1 FROM hocalist.conversation_blocks b
        WHERE b.conversation_id = m.conversation_id
          AND b.revoked_at IS NULL
          AND b.blocked_user_id = m.user_id)
  );
$$;
REVOKE ALL ON FUNCTION hocalist.chat_signal_member(uuid)
  FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION hocalist.chat_signal_member(uuid) TO authenticated;
CREATE POLICY chat_member_signal_read ON hocalist.chat_change_signals
  FOR SELECT TO authenticated
  USING (hocalist.chat_signal_member(conversation_id));

CREATE FUNCTION hocalist.chat_signal_on_message()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  INSERT INTO hocalist.chat_change_signals(conversation_id) VALUES (NEW.conversation_id);
  DELETE FROM hocalist.chat_change_signals
    WHERE conversation_id = NEW.conversation_id
      AND created_at < now() - interval '15 minutes';
  RETURN NEW;
END; $$;
REVOKE ALL ON FUNCTION hocalist.chat_signal_on_message()
  FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER chat_signal_message
  AFTER INSERT ON hocalist.conversation_messages
  FOR EACH ROW EXECUTE FUNCTION hocalist.chat_signal_on_message();

DO $chat_signal_publication$
DECLARE
  v_added boolean := false;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    IF NOT EXISTS (
      SELECT 1 FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime'
        AND schemaname = 'hocalist'
        AND tablename = 'chat_change_signals'
    ) THEN
      ALTER PUBLICATION supabase_realtime ADD TABLE hocalist.chat_change_signals;
      v_added := true;
    END IF;
  END IF;
  RAISE NOTICE 'hocalist chat_change_signals publication added: %', v_added;
END
$chat_signal_publication$;

DO $hocalist_chat_signal_postapply$
DECLARE
  v_issues text[] := ARRAY[]::text[];
  v_public_tables text[];
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgrelid = 'hocalist.conversation_messages'::regclass
      AND tgname = 'chat_signal_message' AND NOT tgisinternal
  ) THEN
    v_issues := array_append(v_issues, 'missing chat signal trigger');
  END IF;
  IF NOT has_table_privilege('authenticated','hocalist.chat_change_signals','SELECT')
     OR has_table_privilege('anon','hocalist.chat_change_signals','SELECT')
     OR has_table_privilege('service_role','hocalist.chat_change_signals','SELECT') THEN
    v_issues := array_append(v_issues, 'signal table grants differ from the reviewed shape');
  END IF;
  IF NOT has_function_privilege('authenticated','hocalist.chat_signal_member(uuid)','EXECUTE')
     OR has_function_privilege('anon','hocalist.chat_signal_member(uuid)','EXECUTE')
     OR has_function_privilege('service_role','hocalist.chat_signal_member(uuid)','EXECUTE') THEN
    v_issues := array_append(v_issues, 'signal policy helper grants differ from the reviewed shape');
  END IF;
  IF position('conversation_blocks' in pg_get_functiondef(
       to_regprocedure('hocalist.chat_signal_member(uuid)'))) = 0
     OR position('memberships' in pg_get_functiondef(
       to_regprocedure('hocalist.chat_signal_member(uuid)'))) = 0 THEN
    v_issues := array_append(v_issues, 'signal policy does not mirror the conversation read fence');
  END IF;
  IF has_function_privilege('authenticated','hocalist.chat_is_member(uuid,uuid)','EXECUTE')
     OR has_function_privilege('authenticated','hocalist.chat_signal_on_message()','EXECUTE') THEN
    v_issues := array_append(v_issues, 'internal signal helper is executable by a client role');
  END IF;
  IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid='hocalist.chat_change_signals'::regclass) THEN
    v_issues := array_append(v_issues, 'signal table RLS is disabled');
  END IF;
  -- Never allow a broad publication of private tables: only the single signal
  -- table may appear for the hocalist schema.
  SELECT array_agg(tablename ORDER BY tablename) INTO v_public_tables
  FROM pg_publication_tables
  WHERE pubname = 'supabase_realtime' AND schemaname = 'hocalist';
  IF v_public_tables IS NOT NULL
     AND v_public_tables <> ARRAY['chat_change_signals']::text[] THEN
    v_issues := array_append(v_issues, 'hocalist publication exposes more than chat_change_signals');
  END IF;
  IF coalesce(array_length(v_issues, 1), 0) > 0 THEN
    RAISE EXCEPTION 'hocalist chat signal post-apply verification failed: %',
      array_to_string(v_issues, ' | ');
  END IF;
END
$hocalist_chat_signal_postapply$;
-- ---------------------------------------------------------------------------
-- 155_media_block_fence.sql
-- ---------------------------------------------------------------------------
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';
DO $media_fence_guard$
DECLARE
  v_def text;
  v_hash text;
  -- Exact reviewed definitions (md5 of pg_get_functiondef, CR-normalized).
  -- Only these two bodies are accepted; a permissive body that merely mentions
  -- `conversation_blocks` (for example in a comment) is drift and is rejected
  -- before any mutation.
  v_legacy constant text := '6a87ca8a3b753bcf7e59b4b692cc10b3';
  v_corrected constant text := 'b1671c7e2e91a48ace319e3f94583e63';
BEGIN
  IF to_regclass('hocalist.conversation_messages') IS NULL
     OR to_regclass('hocalist.conversation_members') IS NULL
     OR to_regclass('hocalist.conversation_blocks') IS NULL THEN
    RAISE EXCEPTION 'Chat block/attachment foundation is missing';
  END IF;

  IF to_regprocedure('hocalist.media_read_chat(uuid,uuid)') IS NULL THEN
    RAISE NOTICE 'chat 011 is not applied; media_read_chat fence deferred until it is';
    RETURN;
  END IF;
  -- The helper can only exist when the media module is present; assert that
  -- explicitly before replacing anything.
  IF to_regclass('hocalist.media_images') IS NULL
     OR to_regprocedure('hocalist.media_gateway(uuid,text,jsonb)') IS NULL THEN
    RAISE EXCEPTION 'media 100 foundation is missing for the chat attachment helper';
  END IF;

  v_def := pg_get_functiondef(to_regprocedure('hocalist.media_read_chat(uuid,uuid)'));
  v_hash := md5(replace(v_def, chr(13), ''));
  IF v_hash = v_corrected THEN
    RAISE NOTICE 'media_read_chat is already the reviewed corrected definition; nothing to do';
    RETURN;
  END IF;
  IF v_hash <> v_legacy THEN
    RAISE EXCEPTION 'Prerequisite drift: hocalist.media_read_chat(uuid,uuid)';
  END IF;

  EXECUTE $fenced$
CREATE OR REPLACE FUNCTION hocalist.media_read_chat(p_user uuid, p_image uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (
    SELECT 1 FROM hocalist.conversation_messages msg
    JOIN hocalist.conversation_members cm ON cm.conversation_id = msg.conversation_id
    WHERE msg.attachment_media_ids ? p_image::text
      AND cm.user_id = p_user AND cm.revoked_at IS NULL
      AND EXISTS (
        SELECT 1 FROM hocalist.memberships m
        WHERE m.id = cm.profile_id AND m.user_id = p_user
          AND m.role = cm.role AND m.status = 'active')
      AND NOT EXISTS (
        SELECT 1 FROM hocalist.memberships r
        WHERE r.user_id = p_user AND r.status IN ('restricted','disabled'))
      AND NOT EXISTS (
        SELECT 1 FROM hocalist.conversation_blocks b
        WHERE b.conversation_id = msg.conversation_id
          AND b.revoked_at IS NULL
          AND b.blocked_user_id = p_user)
  );
$$;
$fenced$;

  -- Re-assert the reviewed grant shape (the replacement preserves ACLs, but a
  -- standalone re-run on a partially changed database must not widen access).
  REVOKE ALL ON FUNCTION hocalist.media_read_chat(uuid,uuid)
    FROM PUBLIC, anon, authenticated, service_role;
END
$media_fence_guard$;

DO $media_fence_postapply$
DECLARE
  v_issues text[] := ARRAY[]::text[];
  v_hash text;
BEGIN
  IF to_regprocedure('hocalist.media_read_chat(uuid,uuid)') IS NOT NULL THEN
    v_hash := md5(replace(pg_get_functiondef(
      to_regprocedure('hocalist.media_read_chat(uuid,uuid)')), chr(13), ''));
    IF v_hash <> 'b1671c7e2e91a48ace319e3f94583e63' THEN
      v_issues := array_append(
        v_issues, 'media_read_chat is not the reviewed corrected definition');
    END IF;
    IF has_function_privilege('authenticated','hocalist.media_read_chat(uuid,uuid)','EXECUTE')
       OR has_function_privilege('anon','hocalist.media_read_chat(uuid,uuid)','EXECUTE')
       OR has_function_privilege('service_role','hocalist.media_read_chat(uuid,uuid)','EXECUTE') THEN
      v_issues := array_append(v_issues, 'media_read_chat must stay an internal helper');
    END IF;
  END IF;
  IF to_regprocedure('hocalist.media_gateway(uuid,text,jsonb)') IS NOT NULL
     AND (NOT has_function_privilege('service_role','hocalist.media_gateway(uuid,text,jsonb)','EXECUTE')
       OR has_function_privilege('authenticated','hocalist.media_gateway(uuid,text,jsonb)','EXECUTE')) THEN
    v_issues := array_append(v_issues, 'media gateway grants changed');
  END IF;
  IF coalesce(array_length(v_issues, 1), 0) > 0 THEN
    RAISE EXCEPTION 'hocalist media fence post-apply verification failed: %',
      array_to_string(v_issues, ' | ');
  END IF;
END
$media_fence_postapply$;
-- Shared verification block for the communications-completion rollout. The
-- generator embeds this verbatim in both apply.sql and verify.sql; the rollout
-- test asserts that.
DO $hocalist_communication_verify$
DECLARE
  v_issues text[] := ARRAY[]::text[];
  v_fn text;
  v_entry text;
  v_table text;
  v_trigger text;
  v_public_tables text[];
BEGIN
  -- New tables: present, RLS enabled, service/anon never granted.
  FOREACH v_table IN ARRAY ARRAY['conversation_blocks','chat_change_signals'] LOOP
    IF to_regclass('hocalist.' || v_table) IS NULL THEN
      v_issues := array_append(v_issues, 'missing table: ' || v_table);
    ELSIF NOT (SELECT relrowsecurity FROM pg_class
               WHERE oid = ('hocalist.' || v_table)::regclass) THEN
      v_issues := array_append(v_issues, 'RLS disabled: ' || v_table);
    ELSIF has_table_privilege('anon', 'hocalist.' || v_table, 'SELECT')
       OR has_table_privilege('service_role', 'hocalist.' || v_table, 'SELECT') THEN
      v_issues := array_append(v_issues, 'unexpected table grant: ' || v_table);
    END IF;
  END LOOP;
  IF has_table_privilege('authenticated','hocalist.conversation_blocks','SELECT') THEN
    v_issues := array_append(v_issues, 'conversation_blocks must not be client-readable');
  END IF;
  IF NOT has_table_privilege('authenticated','hocalist.chat_change_signals','SELECT') THEN
    v_issues := array_append(v_issues, 'chat_change_signals must be readable for Realtime authorization');
  END IF;

  -- Client RPCs: authenticated only.
  FOREACH v_fn IN ARRAY ARRAY[
    'chat_block(uuid,text)','chat_unblock(uuid)','chat_block_state(uuid)',
    'chat_search(text,integer,text,uuid)','chat_search_inbox(text,integer,text)',
    'call_status(uuid,bigint)'] LOOP
    IF NOT has_function_privilege('authenticated', 'hocalist.' || v_fn, 'EXECUTE')
       OR has_function_privilege('anon', 'hocalist.' || v_fn, 'EXECUTE')
       OR has_function_privilege('service_role', 'hocalist.' || v_fn, 'EXECUTE') THEN
      v_issues := array_append(v_issues, 'client function grants are wrong: ' || v_fn);
    END IF;
  END LOOP;

  -- Internal helpers and producers: no client or service execution. The
  -- signal policy helper is intentionally authenticated-executable and is
  -- covered by the client-function grant checks above.
  FOREACH v_fn IN ARRAY ARRAY[
    'chat_block_enforce_insert()','chat_signal_on_message()',
    'notification_on_call_ringing()','notification_on_call_status()'] LOOP
    IF has_function_privilege('authenticated', 'hocalist.' || v_fn, 'EXECUTE')
       OR has_function_privilege('anon', 'hocalist.' || v_fn, 'EXECUTE') THEN
      v_issues := array_append(v_issues, 'internal function is executable: ' || v_fn);
    END IF;
  END LOOP;
  IF has_function_privilege('authenticated','hocalist.chat_is_member(uuid,uuid)','EXECUTE') THEN
    v_issues := array_append(v_issues, 'chat_is_member must stay internal');
  END IF;
  IF NOT has_function_privilege('service_role','hocalist.notification_enqueue_meeting_reminders(integer,integer)','EXECUTE')
     OR has_function_privilege('authenticated','hocalist.notification_enqueue_meeting_reminders(integer,integer)','EXECUTE') THEN
    v_issues := array_append(v_issues, 'reminder entry-point grants are wrong');
  END IF;

  -- Replaced definitions carry the enforcement markers.
  IF position('conversation_blocked' in pg_get_functiondef(
       to_regprocedure('hocalist.chat_assert_participant(uuid,uuid)'))) = 0
     OR position('conversation_blocks' in pg_get_functiondef(
       to_regprocedure('hocalist.chat_inbox(integer,text)'))) = 0 THEN
    v_issues := array_append(v_issues, 'chat read enforcement was not applied');
  END IF;
  IF position('conversation_blocks' in pg_get_functiondef(
       to_regprocedure('hocalist.chat_signal_member(uuid)'))) = 0
     OR position('memberships' in pg_get_functiondef(
       to_regprocedure('hocalist.chat_signal_member(uuid)'))) = 0 THEN
    v_issues := array_append(v_issues, 'signal policy does not mirror the conversation read fence');
  END IF;

  -- Optional chat 011 attachment helper: must be the exact reviewed corrected
  -- definition when present, deferred otherwise. A permissive body that merely
  -- mentions a table name is not accepted, and the helper must never be client-
  -- or service-executable.
  IF to_regprocedure('hocalist.media_read_chat(uuid,uuid)') IS NOT NULL THEN
    IF md5(replace(pg_get_functiondef(
         to_regprocedure('hocalist.media_read_chat(uuid,uuid)')),chr(13),''))
       <> 'b1671c7e2e91a48ace319e3f94583e63' THEN
      v_issues := array_append(v_issues, 'media_read_chat is not the reviewed corrected definition');
    END IF;
    IF has_function_privilege('authenticated','hocalist.media_read_chat(uuid,uuid)','EXECUTE')
       OR has_function_privilege('anon','hocalist.media_read_chat(uuid,uuid)','EXECUTE')
       OR has_function_privilege('service_role','hocalist.media_read_chat(uuid,uuid)','EXECUTE') THEN
      v_issues := array_append(v_issues, 'media_read_chat must stay internal');
    END IF;
  END IF;

  -- Triggers.
  FOREACH v_entry IN ARRAY ARRAY[
    'conversation_messages:chat_block_enforce_message',
    'conversation_messages:chat_signal_message',
    'calls:notification_call_ringing',
    'calls:notification_call_status'] LOOP
    v_table := split_part(v_entry, ':', 1);
    v_trigger := split_part(v_entry, ':', 2);
    IF NOT EXISTS (
      SELECT 1 FROM pg_trigger
      WHERE tgrelid = ('hocalist.' || v_table)::regclass
        AND tgname = v_trigger AND NOT tgisinternal
    ) THEN
      v_issues := array_append(v_issues, 'missing trigger: ' || v_entry);
    END IF;
  END LOOP;

  -- Publication containment: at most the single content-free signal table.
  SELECT array_agg(tablename ORDER BY tablename) INTO v_public_tables
  FROM pg_publication_tables
  WHERE pubname = 'supabase_realtime' AND schemaname = 'hocalist';
  IF v_public_tables IS NOT NULL
     AND v_public_tables <> ARRAY['chat_change_signals']::text[] THEN
    v_issues := array_append(v_issues, 'hocalist publication exposes more than chat_change_signals');
  END IF;

  -- Deployed baseline grants unchanged.
  IF NOT has_function_privilege('authenticated','hocalist.chat_send(uuid,text,text)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.chat_messages(uuid,integer,uuid)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.chat_inbox(integer,text)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.call_command(text,jsonb)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.notification_inbox(integer,text)','EXECUTE')
     OR NOT has_function_privilege('authenticated','hocalist.account_command(text,text,jsonb)','EXECUTE')
     OR has_function_privilege('authenticated','hocalist.notification_emit(uuid,uuid,text,uuid,text,text,text,jsonb)','EXECUTE') THEN
    v_issues := array_append(v_issues, 'deployed chat/call/notification/account grants changed');
  END IF;

  IF coalesce(array_length(v_issues, 1), 0) > 0 THEN
    RAISE EXCEPTION 'hocalist communications-completion verification failed: %',
      array_to_string(v_issues, ' | ');
  END IF;
END
$hocalist_communication_verify$;
COMMIT;
